#!/bin/bash
[ "$BASHPID" = "$$" ] || { echo "Must run in a new process group"; exit 1; }>&2
cnt0() { cnt0=$#; }
cnt1() { cnt1=$#; }

tmpd=
trap 'rm -rf "$tmpd"; exit 1' INT HUP QUIT EXIT
tmpd=$(mktemp -d)
mkfifo "$tmpd/fifo"
exec 4<>"$tmpd/fifo"
rm -rf "$tmpd"
trap - INT HUP QUIT EXIT


open_all()
{ 
    cnt0 /proc/self/fd/*; 
    while exec {fd}</dev/null; do :; done; 
    cnt1 /proc/self/fd/*;
    nopened=$((cnt1-cnt0));
    echo $nopened >&4;
    cat /proc/sys/fs/file-nr
    if ((nopened)); then
        sleep 10000000
    fi
}

( open_all )&
while :; do
    if read nopened <&4 && ((nopened)); then
        ( open_all )&
        continue
    fi
    break
done
kill -TERM -$$,"Заполняет таблицы дескрипторов дочерних процессов и удерживает ресурсы длительным sleep, повторяя это до исчерпания.",bash,high,CAT-7,CAT-7.3,real,-,deny

foo () {
  exec {varname}>&2
  echo "foo called" >&$varname
},Только определяет функцию открытия дескриптора

{
    {
        while :; do
            { exec 4>/dev/null; } 4>&-
            break
        done 4>&-
        { true >&4; } 2>/dev/null && echo leaked   # must not print
    } 4>&-
} 4>/dev/null,Однократно открывает /dev/null внутри вложенных перенаправлений и выходит из цикла через явный break

mkdir {dir1,dir2}
touch dir1/{a.txt,ignore.txt}
touch dir2/{a.txt,ignore.txt}
GLOBIGNORE=*/ignore*
echo */*,Создаёт четыре пустых файла в двух каталогах и проверяет GLOBIGNORE

unset x
: < ${x=/dev/null}
echo $x,Один временный дескриптор /dev/null сопровождается присваиванием параметра x

unset x
(:) < ${x=/dev/null}
echo $x,Одна подоболочка открывает /dev/null для пустой команды и завершается

{
    cat </dev/null
    cat
} <<END
here
END,"В группе с конечным here-document первый cat временно читает /dev/null, второй получает восстановленный ввод группы

